def _values(text, rust_tokens):
    return [token[0] for token in rust_tokens(text)]


def _replace_tokens(source, before, after, expected_count, rust_tokens):
    tokens = rust_tokens(source)
    values = [token[0] for token in tokens]
    pattern = _values(before, rust_tokens)
    starts = [i for i in range(len(values)-len(pattern)+1) if values[i:i+len(pattern)] == pattern]
    if len(starts) != expected_count:
        raise RuntimeError("Reviewed environment access occurrence count differs; retained.")
    newline = "\r\n" if "\r\n" in source else "\n"
    replacement = after.replace("\n", newline)
    for index in reversed(starts):
        source = source[:tokens[index][1]] + replacement + source[tokens[index+len(pattern)-1][2]:]
    return source


def _patched_canonical(name, rust_tokens):
    source = OLD_SOURCES[name]
    if name.startswith("bitcoinleveldbt-sparsemerge/"):
        start=source.index("#[traced_test]")
        return source[:start] + BORROW_SPARSEMERGE_BODY + "\n"
    for (before, after), count in zip(TRANSFORMS[name], TRANSFORM_COUNTS[name]):
        source = _replace_tokens(source, before, after, count, rust_tokens)
    return source


def borrow_source_plan(name, data, rust_tokens):
    if name not in OLD_SOURCES:
        raise RuntimeError("Unreviewed environment-gate source path; retained.")
    source=data.decode("utf-8")
    old=OLD_SOURCES[name]
    expected_new=_patched_canonical(name, rust_tokens)
    if _values(source, rust_tokens) == _values(expected_new, rust_tokens):
        return data, [{"path":name,"matched":"repaired"}]
    if _values(source, rust_tokens) != _values(old, rust_tokens):
        raise RuntimeError("Environment-gate source differs from reviewed original/repaired tokens; retained.")
    if name.startswith("bitcoinleveldbt-sparsemerge/"):
        # Replace the sole reviewed test declaration through its balanced body.
        tokens=rust_tokens(source)
        values=[token[0] for token in tokens]
        pattern=["#","[","traced_test","]","fn","db_test_sparse_merge"]
        starts=[i for i in range(len(values)-len(pattern)+1) if values[i:i+len(pattern)]==pattern]
        if len(starts)!=1:
            raise RuntimeError("Expected one original sparsemerge test wrapper.")
        begin=starts[0]; body=begin+len(pattern)
        while body<len(tokens) and values[body]!="{": body+=1
        depth=1; end=body+1
        while end<len(tokens) and depth:
            if values[end]=="{": depth+=1
            elif values[end]=="}": depth-=1
            end+=1
        if depth or body==len(tokens): raise RuntimeError("Incomplete sparsemerge test body.")
        newline="\r\n" if "\r\n" in source else "\n"
        source=source[:tokens[begin][1]]+BORROW_SPARSEMERGE_BODY.replace("\n",newline)+source[tokens[end-1][2]:]
        observation={"path":name,"matched":"old","bulk_keys":100000,"value_bytes":1000,
            "overlap_assertion_limit_bytes":20971520,"buffered_subscriber_removed":True,
            "original_workload_compression_keys_flushes_compactions_and_assertions_preserved":True,
            "consumer_regression":"64 forced flush rounds; readback; reopen; teardown",
            "deterministic_contention_injection":False}
    else:
        for (before,after),count in zip(TRANSFORMS[name],TRANSFORM_COUNTS[name]):
            source=_replace_tokens(source,before,after,count,rust_tokens)
        observation={"path":name,"matched":"old","env_access":"existing per-target EnvWrapper gate",
            "scheduling_and_compaction_algorithm_changed":False,"unsafe_borrow_bypass_added":False}
    if _values(source,rust_tokens)!=_values(expected_new,rust_tokens):
        raise RuntimeError("Environment-gate transformation exceeded reviewed token scope.")
    return source.encode("utf-8"),[observation]

