def checked_import(path, digest, name):
    path = Path(path)
    if path.is_symlink() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
        raise RuntimeError("Reviewed controller differs: " + str(path))
    sys.dont_write_bytecode = True
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def require_run(result):
    if result.get("verified") is not True or result.get("outcome") != "exited" or result.get("exit_code") != 0:
        raise RuntimeError("Protected phase failed: " + str(result.get("label")) + ", outcome="
                           + str(result.get("outcome")) + ", exit=" + str(result.get("exit_code")))


def validate_result(result):
    cases = result.get("cases", {})
    if (result.get("outcome") != "passed" or result.get("inputs_preserved") is not True
            or result.get("full_coverage_claimed") is not False
            or result.get("original_case_completed") is not True
            or result.get("regression_completed") is not True
            or set(cases) != {"db_test_env_borrow_gate_rotation", "db_test_sparse_merge"}):
        raise RuntimeError("SparseMerge full original scenario has not passed its two-case qualification.")
    for name, row in cases.items():
        if (row.get("passed"), row.get("failed"), row.get("ignored")) != (1, 0, 0):
            raise RuntimeError("SparseMerge case did not pass exactly once: " + name)


def worker_guard(runner, final, head, files, old, pending, initial=False):
    runner.guard_operations()
    if runner.git("symbolic-ref", "--quiet", "--short", "HEAD") != BRANCH or runner.git("rev-parse", "HEAD") != head:
        raise RuntimeError("SparseMerge branch advanced beyond its owned checkpoint.")
    dirty = final.names(runner, "diff", "--no-renames", "--name-only") | final.names(runner, "diff", "--cached", "--no-renames", "--name-only")
    untracked = final.names(runner, "ls-files", "--others", "--exclude-standard")
    if (dirty | untracked) - (PATHS if pending else set()):
        raise RuntimeError("SparseMerge worktree contains unrelated changes; retained.")
    configurations = {".cargo/config", ".cargo/config.toml"}
    tracked = final.names(runner, "ls-files", "--", *sorted(configurations))
    if any((runner.repo / name).exists() or (runner.repo / name).is_symlink() for name in configurations - tracked):
        raise RuntimeError("Untracked/ignored Cargo configuration requires review.")
    for name in PATHS:
        path = runner.repo / name
        for part in [path, *path.parents]:
            if part == runner.repo:
                break
            if part.is_symlink() or (part != path and part.exists() and not part.is_dir()):
                raise RuntimeError("Owned path has a symlink or non-directory ancestor: " + name)
        expected = files.get(name)
        current = path.read_bytes() if path.exists() else None
        indexed = final.blob(runner, "", name, False)
        current_allowed = {expected, old.get(name)} if initial and pending else {expected}
        index_allowed = {expected, old.get(name)} if pending else {expected}
        if current not in current_allowed or indexed not in index_allowed:
            raise RuntimeError("Unexpected owned working/index content retained: " + name)
        if path.exists() and path.stat().st_mode & 0o7777 != (0o755 if name in EXECUTABLES else 0o644):
            raise RuntimeError("Unexpected owned permissions retained: " + name)


def own_commit(runner, final, head, files):
    return (runner.git("show", "-s", "--format=%P", head).split() == [BASE]
            and final.changed(runner, BASE, head) == PATHS
            and all(final.blob(runner, head, name, False) == data
                    and runner.git("ls-tree", head, "--", name).startswith(
                        ("100755" if name in EXECUTABLES else "100644") + " blob ")
                    for name, data in files.items()))


def retained_diagnostic_snapshot(origin, common, final):
    """Record the pending 001 journal/index/owned files without editing them."""
    previous_metadata = common / "codex-repairs" / "leveldb-sparsemerge-diagnostic001"
    previous_worker = origin.parent / (origin.name + "-sparsemerge-repair")
    result = {"journal": {name: final.fingerprint(previous_metadata / name)
                           for name in ("state.json", "worktree.json")},
              "worktree": str(previous_worker), "present": previous_worker.exists()}
    if previous_worker.is_symlink():
        result["worker_symlink"] = final.fingerprint(previous_worker)
        return result
    if not previous_worker.exists():
        return result
    if not previous_worker.is_dir():
        result["worker_file"] = final.fingerprint(previous_worker)
        return result
    owned = (SOURCE, "contrib/test/sparsemerge_resource_guard.py", "contrib/test/leveldb-sparsemerge.py",
             "contrib/repair/bitcoinleveldb-sparsemerge-diagnostic001.py", "doc/testing/leveldb-sparsemerge.md",
             "doc/repair/leveldb-sparsemerge-diagnostic001.json")
    result["files"] = {name: final.fingerprint(previous_worker / name) for name in owned}
    dotgit = previous_worker / ".git"
    result["git_metadata"] = final.fingerprint(dotgit)
    if dotgit.is_symlink() or not dotgit.is_file() or dotgit.stat().st_size > 16384:
        raise RuntimeError("Pending sparsemerge001 worktree metadata requires review; retained.")
    value = dotgit.read_text().strip()
    if not value.startswith("gitdir: "):
        raise RuntimeError("Pending sparsemerge001 has unsupported worktree metadata; retained.")
    gitdir = (previous_worker / value[8:]).resolve()
    if not gitdir.is_relative_to(common.resolve()):
        raise RuntimeError("Pending sparsemerge001 worktree metadata leaves this repository; retained.")
    result["index"] = final.fingerprint(gitdir / "index")
    return result


def run_install(origin, script_path):
    report = {"workflow": WORKFLOW, "outcome": "failed", "phase": "preflight", "base": BASE, "branch": BRANCH,
              "merge": "not performed at this checkpoint", "tag": "not performed at this checkpoint",
              "full_coverage_claimed": False,
              "unsafe_buffered_baseline": "not run; original source retained at base"}
    locks = []
    runner = final = repair = original_guard = directory = shared_lock = None
    failure = None
    verification = None
    try:
        dev = checked_import(origin / ENV_SCRIPT, ENV_SHA, "accepted_devshell001")
        final = dev.trusted_finalizer(origin)
        if (Path(final.bootstrap_git(origin, "rev-parse", "--show-toplevel")).resolve() != origin
                or final.bootstrap_git(origin, "rev-parse", "HEAD") != BASE
                or final.bootstrap_git(origin, "symbolic-ref", "--quiet", "--short", "HEAD") != "master"):
            raise RuntimeError("--repo must identify original master at the accepted environment checkpoint.")
        common = Path(final.bootstrap_git(origin, "rev-parse", "--path-format=absolute", "--git-common-dir"))
        metadata = common / "codex-repairs" / WORKFLOW
        metadata.mkdir(parents=True, exist_ok=True)
        shared_path = common / "codex-repairs" / "leveldb-resource-tests001" / "run.lock"
        shared_path.parent.mkdir(parents=True, exist_ok=True)
        for path in (common / "codex-repairs" / final.REPAIR / "run.lock",
                     common / "codex-repairs" / dev.WORKFLOW / "run.lock", metadata / "run.lock", shared_path):
            if path.is_symlink():
                raise RuntimeError("Workflow lock is a symlink.")
            lock = path.open("a+"); locks.append(lock); fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        shared_lock = locks[-1]
        repair, runner = final.trusted_coverage(origin).load_repair_runner(origin, origin)
        runner.env["GIT_OPTIONAL_LOCKS"] = "0"
        directory = metadata / "runs" / (dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ") + "-" + uuid.uuid4().hex[:8])
        directory.mkdir(parents=True)
        runner.directory, runner.log, runner.report = directory, (directory / "run.log").open("w", buffering=1), report
        shared_cache = common / "codex-repairs" / "leveldb-issue178-diagnostic001" / "cargo-target"
        ordinary_shared_cache = shared_cache.is_dir() and not shared_cache.is_symlink()
        for parent in shared_cache.parents:
            if parent == common:
                break
            ordinary_shared_cache = ordinary_shared_cache and not parent.is_symlink()
        target = shared_cache if ordinary_shared_cache else metadata / "cargo-target"
        report["cargo_cache_reused_from_issue178"] = ordinary_shared_cache
        report.update(origin_repository=str(origin), run_directory=str(directory), cargo_target_directory=str(target))
        final.environment_guard(runner); runner.guard_operations()
        if set(PAYLOADS) != {GUARD_PATH, ROUTINE_PATH, DOCUMENT_PATH}:
            raise RuntimeError("Reviewed sparsemerge payload set differs.")
        if (origin / "shell.nix").read_bytes() != final.blob(runner, BASE, "shell.nix"):
            raise RuntimeError("Accepted native shell changed.")
        old = {name: final.blob(runner, BASE, name, False) for name in PATHS}
        if any(old[name] is None for name in SOURCE_PATHS) or any(old[name] is not None for name in PATHS - SOURCE_PATHS):
            raise RuntimeError("SparseMerge base source or new path scope differs.")
        files = dict(PAYLOADS, **{REPLAY_PATH: script_path.read_bytes()})
        report["source_guard"] = []
        for name in sorted(SOURCE_PATHS):
            patched, observations = borrow_source_plan(name, old[name], repair.rust_tokens)
            files[name] = patched
            report["source_guard"].append({"path": name, "baseline_sha256": final.sha(old[name]),
                                           "patched_sha256": final.sha(patched), "observations": observations})
        before = final.userdata(runner, PATHS)
        original_index = final.fingerprint(Path(runner.git("rev-parse", "--path-format=absolute", "--git-path", "index")))
        snapshot_tag = runner.git("rev-parse", "refs/tags/" + final.TAG)
        preserved_refs = {}
        for ref in PRESERVED_REFS:
            result = runner.capture(["git", "rev-parse", "--verify", ref], check=False)
            preserved_refs[ref] = result.stdout.decode().strip() if result.returncode == 0 else None
        retained_diagnostic = retained_diagnostic_snapshot(origin, common, final)
        report["pending_sparsemerge001_before_sha256"] = final.sha(final.encoded(retained_diagnostic))
        inputs = final.integration_inputs(runner, BASE)
        report["userdata_before_sha256"] = final.sha(final.encoded(before))

        def original_guard():
            saved = runner.repo; runner.repo = origin
            try:
                runner.guard_operations()
                if (runner.git("symbolic-ref", "--quiet", "--short", "HEAD") != "master" or runner.git("rev-parse", "HEAD") != BASE
                        or final.userdata(runner, PATHS) != before
                        or final.fingerprint(Path(runner.git("rev-parse", "--path-format=absolute", "--git-path", "index"))) != original_index):
                    raise RuntimeError("Original branch/index/user-owned state changed; retained.")
                if (final.names(runner, "diff", "--no-renames", "--name-only", BASE)
                        | final.names(runner, "diff", "--cached", "--no-renames", "--name-only", BASE)) & inputs.keys():
                    raise RuntimeError("Original Rust/build inputs changed.")
                if runner.git("rev-parse", "refs/tags/" + final.TAG) != snapshot_tag:
                    raise RuntimeError("Previous snapshot tag changed.")
                for ref, expected in preserved_refs.items():
                    actual = runner.capture(["git", "rev-parse", "--verify", ref], check=False)
                    current = actual.stdout.decode().strip() if actual.returncode == 0 else None
                    if current != expected:
                        raise RuntimeError("Recorded repair ref changed: " + ref)
                if retained_diagnostic_snapshot(origin, common, final) != retained_diagnostic:
                    raise RuntimeError("Pending sparsemerge001 journal/index/owned files changed; retained.")
            finally:
                runner.repo = saved

        original_guard()
        identity = {"workflow": WORKFLOW, "base": BASE, "branch": BRANCH,
                    "file_hashes": {name: final.sha(data) for name, data in files.items()}}
        state_path, layout_path = metadata / "state.json", metadata / "worktree.json"
        if state_path.is_symlink() or layout_path.is_symlink():
            raise RuntimeError("SparseMerge ownership journal is a symlink.")
        state = json.loads(state_path.read_text()) if state_path.exists() else dict(identity, phase="pending")
        if any(state.get(key) != value for key, value in identity.items()) or state.get("blocked_checkpoint"):
            raise RuntimeError("SparseMerge checkpoint journal identity changed; retained.")
        files[RECEIPT_PATH] = final.encoded(state["receipt"]) if state.get("receipt") is not None else None
        worktree = origin.parent / (origin.name + WORKTREE_SUFFIX)
        if worktree.is_symlink() or target.is_symlink():
            raise RuntimeError("SparseMerge worktree/cache path is a symlink.")
        layout = dict(identity, origin=str(origin), path=str(worktree))
        branch = runner.capture(["git", "rev-parse", "--verify", "refs/heads/" + BRANCH], check=False)
        if layout_path.exists():
            if json.loads(layout_path.read_text()) != layout:
                raise RuntimeError("SparseMerge worktree ownership differs.")
        elif worktree.exists() or branch.returncode == 0:
            raise RuntimeError("Existing sparsemerge branch/worktree has no matching ownership journal.")
        else:
            runner.save_state(layout_path, layout)
        runner.save_state(state_path, state)
        boot = directory / "sparsemerge_borrow_resource_guard.py"
        repair.atomic_write(boot, PAYLOADS[GUARD_PATH], 0o755)
        guard_module = checked_import(boot, final.sha(PAYLOADS[GUARD_PATH]), "sparsemerge_borrow_resource_guard002")
        guard = guard_module.Guard(directory / "git-guard", boot, runner.env)
        preflight = guard.preflight(); report["git_preflight"] = preflight; require_run(preflight)

        def guarded_git(label, command, cwd):
            original_guard(); report["phase"] = label
            result = guard.run(label, command, cwd, {}, kind="build")
            report.setdefault("git_readouts", {})[label] = result
            state.setdefault("git_readouts", {})[label] = result
            runner.save_state(state_path, state); require_run(result)
            return result

        if ("worktree " + str(worktree) + "\n") not in final.bootstrap_git(origin, "worktree", "list", "--porcelain"):
            if worktree.exists() or (branch.returncode == 0 and branch.stdout.decode().strip() != BASE):
                raise RuntimeError("SparseMerge worktree setup has unknown existing state.")
            command = ["git", "worktree", "add"] + (["-b", BRANCH, str(worktree), BASE] if branch.returncode else [str(worktree), BRANCH])
            guarded_git("git-worktree-add", command, origin)
        if Path(final.bootstrap_git(worktree, "rev-parse", "--path-format=absolute", "--git-common-dir")).resolve() != common.resolve():
            raise RuntimeError("SparseMerge worktree belongs to another repository.")
        runner.repo = worktree
        checkpoint = state.get("checkpoint")
        head = runner.git("rev-parse", "HEAD")
        if head != BASE:
            if state.get("receipt") is None or checkpoint not in (None, head) or not own_commit(runner, final, head, files):
                raise RuntimeError("SparseMerge branch contains an unowned checkpoint.")
            require_run(state.get("git_readouts", {}).get("git-commit", {}))
            validate_result(state["receipt"]["verification"])
            checkpoint = state["checkpoint"] = head
        elif checkpoint is not None:
            raise RuntimeError("Recorded sparsemerge checkpoint no longer matches its branch.")
        worker_guard(runner, final, checkpoint or BASE, files, old, not checkpoint, initial=not checkpoint)
        if not checkpoint:
            for name, data in files.items():
                if data is not None:
                    repair.atomic_write(worktree / name, data, 0o755 if name in EXECUTABLES else 0o644)
        routine = checked_import(worktree / ROUTINE_PATH, final.sha(PAYLOADS[ROUTINE_PATH]), "routine_sparsemerge_borrow002")

        def before_phase(label):
            report["phase"] = label; runner.say("SparseMerge phase: " + label)
            original_guard(); worker_guard(runner, final, checkpoint or BASE, files, old, not checkpoint)

        fcntl.flock(shared_lock, fcntl.LOCK_UN)
        try:
            verification = routine.verify(worktree, target, directory / "verification", before_phase=before_phase)
        except BaseException:
            evidence = directory / "verification" / "VERIFICATION_RETURN.json"
            if evidence.is_file() and not evidence.is_symlink() and evidence.stat().st_size <= 8 * 1024 * 1024:
                report["verification"] = json.loads(evidence.read_text())
            raise
        finally:
            fcntl.flock(shared_lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        report["verification"] = verification
        state["last_verification"] = verification; runner.save_state(state_path, state)
        validate_result(verification)
        original_guard(); worker_guard(runner, final, checkpoint or BASE, files, old, not checkpoint)
        if not checkpoint:
            receipt = {"workflow": WORKFLOW, "base": BASE, "file_hashes": identity["file_hashes"],
                       "verification": verification, "full_coverage_claimed": False,
                       "production_database_law_changed": True,
                       "compaction_algorithm_changed": False,
                       "unsafe_buffered_baseline": report["unsafe_buffered_baseline"]}
            state.update(receipt=receipt, phase="validated"); runner.save_state(state_path, state)
            files[RECEIPT_PATH] = final.encoded(receipt)
            repair.atomic_write(worktree / RECEIPT_PATH, files[RECEIPT_PATH], 0o644)
            for name in sorted(PATHS):
                runner.git("add", "--chmod=" + ("+x" if name in EXECUTABLES else "-x"), "--", name)
            original_guard(); worker_guard(runner, final, BASE, files, old, True)
            message = directory / "commit-message.txt"
            message.write_text("fix: serialize memtable rotation environment access\n\n"
                               "Serialize environment access around memtable rotation; retain the original sparsemerge workload and overlap assertions.\n"
                               "The targeted rotation regression and original sparsemerge regression passed under verified resource limits.\n"
                               "No compaction algorithm change or full coverage claim.\n\nRepair-Workflow: " + WORKFLOW + "\nBase: " + BASE + "\n")
            guarded_git("git-commit", ["git", "commit", "--file", str(message)], worktree)
            checkpoint = runner.git("rev-parse", "HEAD")
            if not own_commit(runner, final, checkpoint, files):
                state["blocked_checkpoint"] = checkpoint; runner.save_state(state_path, state)
                raise RuntimeError("SparseMerge commit exceeded its exact " + str(len(PATHS)) + "-file scope; retained.")
        original_guard(); worker_guard(runner, final, checkpoint, files, old, False)
        state.update(checkpoint=checkpoint, phase="complete"); runner.save_state(state_path, state)
        report.update(outcome="passed", phase="complete", checkpoint=checkpoint, worktree=str(worktree), original_preserved=True,
                      userdata_after_sha256=final.sha(final.encoded(final.userdata(runner, PATHS))), preserved_refs=preserved_refs,
                      pending_sparsemerge001_preserved=True,
                      pending_sparsemerge001_after_sha256=final.sha(final.encoded(retained_diagnostic_snapshot(origin, common, final))))
    except KeyboardInterrupt:
        failure = "Interrupted; owned files and logs retained. No unrestricted retry was attempted."
    except Exception as error:
        failure = type(error).__name__ + ": " + str(error)
        report["exception_traceback"] = traceback.format_exc().splitlines()
    finally:
        if failure:
            observed = report.get("verification", verification or {})
            report.update(outcome="inconclusive" if observed.get("outcome") == "inconclusive" else "failed", error=failure)
        if runner is not None:
            try:
                if original_guard:
                    original_guard(); report["original_preserved"] = True
                    report["pending_sparsemerge001_preserved"] = True
                    report["pending_sparsemerge001_after_sha256"] = final.sha(final.encoded(
                        retained_diagnostic_snapshot(origin, common, final)))
                report.update(original_head=final.bootstrap_git(origin, "rev-parse", "HEAD"),
                              original_status=final.bootstrap_git(origin, "status", "--short"))
            except Exception as error:
                report.update(outcome="failed", original_preserved=False, preservation_error=str(error))
            if directory is not None:
                report["return_file"] = str(directory / "SPARSEMERGE_BORROW_RETURN.txt")
                try:
                    repair.atomic_write(Path(report["return_file"]), final.encoded(report), 0o600)
                except Exception as error:
                    report.update(outcome="failed", finalization_error=str(error))
            if runner.log:
                runner.log.close()
        for lock in reversed(locks):
            lock.close()
        print("BEGIN_SPARSEMERGE_BORROW_RETURN"); print(json.dumps(report, indent=2)); print("END_SPARSEMERGE_BORROW_RETURN")
        if report.get("return_file"):
            print("Return file: " + report["return_file"])
    return 0 if report["outcome"] == "passed" else 1


def main():
    parser = argparse.ArgumentParser(description="Repair sparsemerge memtable-rotation access with sparse progress in an isolated, resource-controlled worktree.")
    parser.add_argument("--repo", type=Path, default=Path.home() / "bitcoin-rs")
    args = parser.parse_args()
    return run_install(args.repo.expanduser().resolve(), Path(__file__).resolve())


if __name__ == "__main__":
    sys.exit(main())
